// Map the new status to a friendly WhatsApp message and decide whether
// to send anything. Returns { shouldSend, phone, body } per item.
//
// NocoDB's webhook body shape (see workflow setup notes):
//   $json.body = { rowId, phone, name, service, department,
//                  status, previousStatus }

const body = $json.body ?? {};
const phone        = String(body.phone ?? '').trim();
const name         = body.name ?? 'there';
const service      = body.service ?? 'your case';
const status       = body.status;
const prev         = body.previousStatus;

// Skip if status hasn't actually changed (same firing edge from NocoDB)
if (!status || status === prev) {
  return { json: { shouldSend: false, reason: 'no status change', phone, status, previousStatus: prev } };
}

// Skip if we don't have a phone we can send to
if (!phone) {
  return { json: { shouldSend: false, reason: 'no phone', status } };
}

// Status → message map. Keep messages short, WhatsApp-natural.
const messages = {
  NEW_LEAD:    `Hi ${name}, your inquiry about ${service} has been received. We'll be in touch shortly. 🙏`,
  CONTACTED:   `Hi ${name}, your inquiry about ${service} has been assigned to a specialist. They will reach out soon.`,
  IN_PROGRESS: `Hi ${name}, our team is now working on your ${service} case. We'll keep you posted on progress.`,
  COMPLETED:   `Hi ${name}, great news — your ${service} case is complete! 🎉 Thank you for choosing Ilot.`,
  ON_HOLD:     `Hi ${name}, your ${service} case is currently on hold. Your specialist will be in touch with details.`,
  CANCELLED:   `Hi ${name}, your ${service} case has been cancelled. If this was unintentional, just reply here and we'll sort it.`,
};

const messageBody = messages[status];

if (!messageBody) {
  return { json: { shouldSend: false, reason: 'no message mapped for status', status } };
}

return { json: { shouldSend: true, phone, body: messageBody, status, previousStatus: prev, name, service } };
